function save(){if(filmEditSaveBatch)return;filmSearchIndexCache=new WeakMap();reconcileDuplicateFilmsGlobally();reconcileAllPlaylistPlaceholders();syncPlaylistCollectionNumbers();stateRevision=Date.now();writeLocalSnapshot();persistIndexedState();scheduleFilmSearchIndexWarmup()}
