function pendingCopySettingsSnapshot(film,revision){const entries=[];projects.forEach(project=>(project.films||[]).forEach(item=>{if(sameId(item.id,film.id)||filmsShareIdentifier(item,film))entries.push({projectId:String(project.id),filmId:String(item.id),copies:structuredClone(item.copies||[]),link:String(item.link||""),status:String(item.status||"")})}));return{revision,entries}}
