function activeProject(){return projects.find(p=>p.id===activeProjectId)||projects[0]}
function esc(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function sameId(a,b){return String(a)===String(b)}
