function normalizedPlaylistTitle(value){return String(value||"").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^\p{L}\p{N}]+/gu," ").trim().toLocaleLowerCase("en-US")}
function filmTitleSearchVariants(...values){const variants=[];values.flat().forEach(value=>{const title=String(value||"").trim();if(!title)return;variants.push(title);const conjunction=title.match(/^(.+?)\s+(?:and|&)\s+(.+)$/i);if(conjunction)variants.push(`${conjunction[2]} and ${conjunction[1]}`)});return[...new Map(variants.map(value=>[normalizedPlaylistTitle(value),value])).values()]}
