function copySourceName(link="",storageType="digital",medium=""){if(storageType==="physical")return String(medium||"physisch").trim().toLocaleLowerCase("de");const raw=String(link||"").trim();if(!raw)return"";if(/^file:/i.test(raw))return"lokal";try{const host=new URL(raw).hostname.toLowerCase().replace(/^www\./,""),providers=[[/(^|\.)archive\.org$/,"archive"],[/(^|\.)(youtube\.com|youtu\.be)$/,"youtube"],[/(^|\.)vimeo\.com$/,"vimeo"],[/(^|\.)mubi\.com$/,"mubi"],[/(^|\.)arte\.tv$/,"arte"],[/(^|\.)(netflix\.com)$/,"netflix"],[/(^|\.)(primevideo\.com|amazon\.[a-z.]+)$/,"amazon"],[/(^|\.)(play\.google\.com|tv\.google)$/,"google"]],known=providers.find(([pattern])=>pattern.test(host));return known?.[1]||host.split(".")[0]||"web"}catch{return"web"}}
