  if(f.userRating)detailMeta.push(archiveRatingMarkup(f.userRating));
  if(directorLinks)detailMeta.push(directorLinks);
  $("detailContent").innerHTML=`<div class="detail-layout"><div class="detail-poster" style="${posterStyle(f)}">${cover(f)}<span class="poster-fallback"><strong>${esc(displayTitle)}</strong></span></div><div class="detail-body"><button class="dialog-close" style="float:right" type="button" data-close-detail aria-label="Schließen">×</button><p class="eyebrow">${esc(genreText(display.genre||f.genre)||(series?"Serie":"Film"))}</p><h2>${esc(displayTitle)}</h2><div class="detail-meta">${detailMeta.join(" · ")}</div>${f.countries?`<p class="detail-countries"><strong>Länder</strong> ${esc(f.countries)}</p>`:""}<p>${esc(display.description||"Keine Beschreibung hinterlegt.")}</p>${f.cast?`<p class="detail-cast"><strong>Mit</strong> ${esc(f.cast)}</p>`:""}${detailAvailabilityMarkup(f,copyActions)}<div class="detail-actions">${f.trailer?`<button class="secondary-action" type="button" data-open-trailer="${esc(f.trailer)}">Trailer ansehen</button>`:""}<button class="secondary-action" type="button" data-edit-from-detail="${esc(f.id)}">Bearbeiten</button></div></div></div>`;
