    const identified=imported.films.filter(film=>IMPORT_IDENTIFIER_KEYS.some(key=>film[key])).length;
    toast(`Projekt importiert · ${imported.films.length} Einträge · ${identified} mit ID${identified?" · TMDB-Daten werden geladen …":""}`);
    const enrichment=await enrichImportedProject(imported);
    renderSelectedProject();
