  if(!source||!dest)return;
  const snapshot={projects:structuredClone(projects),playlists:structuredClone(playlists),activeProjectId},row=els.projectList.querySelector(`[data-project-drag="${CSS.escape(String(targetId))}"]`),films=[...(source.films||[])],total=Math.max(films.length,1),started=performance.now(),job=activeBackgroundOperation?.type==="merge"?activeBackgroundOperation:null;
