function migrateSeriesStructures(){let changed=false;projects.forEach(project=>(project.films||[]).forEach(film=>{if(filmMediaType(film)!=="tv"||Array.isArray(film.seasonsData))return;film.seasonsData=normalizedSeriesStructure(film);changed=true}));return changed}
function migrateMisplacedEpisodeRatings(){let changed=false;projects.forEach(project=>(project.films||[]).forEach(film=>{if(filmMediaType(film)!=="tv")return;(film.seasonsData||[]).forEach(season=>(season.episodes||[]).forEach(episode=>(episode.copies||[]).forEach(copy=>{if(copy.storageType!=="physical"&&isMisplacedEpisodeRating(copy.link)){copy.link="";changed=true}})))}));return changed}
function migrateFilmTrailer(film){const link=String(film?.trailer||"").trim();if(!link)return false;film.bonusMaterials=mergeBonusMaterial(filmBonusMaterials({...film,trailer:""}),{title:"Trailer",link,languages:trailerLanguagesByLink.get(link)||[]});delete film.trailer;return true}
