function migrateCopyStatusTimestamps(){let changed=false;const stamp=statusTimeIso();projects.forEach(project=>(project.films||[]).forEach(film=>{if(Array.isArray(film.copies))film.copies.forEach(copy=>{const status=normalizedCopyStatus(copy.status);if(copy.status!==status){copy.status=status;changed=true}if(!copy.statusUpdatedAt){copy.statusUpdatedAt=stamp;changed=true}if(Object.prototype.hasOwnProperty.call(copy,"title")){delete copy.title;changed=true}if(Object.prototype.hasOwnProperty.call(copy,"label")){delete copy.label;changed=true}});(film.seasonsData||[]).forEach(season=>(season.episodes||[]).forEach(episode=>(episode.copies||[]).forEach(copy=>{const status=normalizedCopyStatus(copy.status);if(copy.status!==status){copy.status=status;changed=true}if(!copy.statusUpdatedAt){copy.statusUpdatedAt=stamp;changed=true}})))}));return changed}
