bindSubtitleLiveSeek("subtitleSyncRewind",-1);
bindSubtitleLiveSeek("subtitleSyncForward",1);
$("subtitleSyncSeek").addEventListener("input",()=>{const video=$("subtitleSyncVideo");if(video.duration)video.currentTime=Number($("subtitleSyncSeek").value)/1000*video.duration});
$("subtitleSyncPreview").addEventListener("change",refreshSubtitleSyncPreview);
function changeSubtitleSyncCue(direction){if(!subtitleSyncState)return;subtitleSyncState.cueIndex=Math.max(0,Math.min(subtitleSyncState.cues.length-1,subtitleSyncState.cueIndex+direction));updateSubtitleSyncCue();if(!$("subtitleSyncFollowCue").checked)return;const cue=subtitleSyncState.cues[subtitleSyncState.cueIndex],video=$("subtitleSyncVideo");if(video.duration)video.currentTime=Math.max(0,(cue.start+subtitleSyncState.offset)/1000)}
$("subtitleSyncPrevious").addEventListener("click",()=>changeSubtitleSyncCue(-1));
$("subtitleSyncNext").addEventListener("click",()=>changeSubtitleSyncCue(1));
$("subtitleSyncCorrectedTime").addEventListener("change",()=>{const value=parseSubtitleTime($("subtitleSyncCorrectedTime").value);if(value===null){toast("Bitte die Zeit im Format 00:00:00.000 eingeben");updateSubtitleSyncCue();return}applySubtitleSyncTime(value)});
$("subtitleSyncCapture").addEventListener("click",()=>{if(!subtitleSyncState)return;const video=$("subtitleSyncVideo");video.pause();applySubtitleSyncTime(Math.round(video.currentTime*1000))});
$("subtitleSyncSave").addEventListener("click",()=>{const state=subtitleSyncState,track=editingSubtitleTracks.find(item=>sameId(item.id,state?.trackId));if(!state||!track||!state.changed)return;track.syncCueEdits={...(track.syncCueEdits||{}),[String(state.copyId)]:structuredClone(state.edits)};$("subtitleSyncVideo").pause();$("subtitleSyncDialog").close();renderSubtitleEditor();toast("Untertitelkorrekturen übernommen – Filmeintrag noch speichern")});
$("subtitleSyncDialog").addEventListener("close",()=>{clearSubtitleSyncPreview();$("subtitleSyncVideo").pause();$("subtitleSyncVideo").removeAttribute("src");subtitleSyncState=null});
document.addEventListener("keydown",event=>{if(event.key!=="Enter"||event.isComposing||event.defaultPrevented)return;const input=event.target.closest?.("dialog form input");if(!input||["button","submit","reset","checkbox","radio","file","color","range"].includes(input.type))return;event.preventDefault();input.dispatchEvent(new Event("change",{bubbles:true}))});
$("addPlaylistButton").addEventListener("click",()=>{editingPlaylistId="";$("playlistDialogEyebrow").textContent="Neue Sammlung";$("playlistDialogTitle").textContent="Playlist anlegen";$("playlistDialogSubmit").textContent="Anlegen"},true);
document.addEventListener("click",event=>{const button=event.target.closest?.("[data-rename-playlist]");if(button)openPlaylistDialog(button.dataset.renamePlaylist)});
document.addEventListener("click",event=>{const button=event.target.closest?.("[data-export-letterboxd]");if(button){closeProjectRowMenus();exportPlaylistToLetterboxd(button.dataset.exportLetterboxd)}});
initializeApplication();






































